1565	        for hint in [DID, TEST_HANDLE, "@Alice.Test", "at://alice.test"] {
1566	            assert_eq!(
1567	                resolve_login_hint_to_local_did(&state, hint)
1568	                    .await
1569	                    .as_deref(),
