2646	    /// Serve a client-metadata document at `/oauth/client-metadata.json` on an ephemeral
2647	    /// loopback port; returns the document's URL (which doubles as the client_id). Mirrors
2648	    /// the PAR test harness — routes cannot share test helpers across modules.
2649	    async fn serve_client_metadata(make_json: impl FnOnce(&str) -> String) -> String {
2650	        use std::future::IntoFuture;
2651	
2652	        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
2653	        let url = format!(
2654	            "http://127.0.0.1:{}/oauth/client-metadata.json",
2655	            listener.local_addr().unwrap().port()
2656	        );
2657	        let json = make_json(&url);
2658	        let router = axum::Router::new().route(
2659	            "/oauth/client-metadata.json",
2660	            axum::routing::get(move || {
2661	                let json = json.clone();
2662	                async move { ([("content-type", "application/json")], json) }
2663	            }),
2664	        );
2665	        tokio::spawn(axum::serve(listener, router).into_future());
2666	        url
2667	    }
